18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    OwnerDto toOwnerDto(Owner owner);
26	
27	    Owner toOwner(OwnerDto ownerDto);
28	
29	    @Mapping(target = "id", ignore = true)
30	    @Mapping(target = "pets", ignore = true)
31	    Owner toOwner(OwnerFieldsDto ownerDto);
32	
33	    /**
34	     * Derives the household identifier for the response: the deterministic {@link Household#id} over
35	     * the owner's last name and postcode, so members of one household always report the same id.
36	     * Non-persistent, so it never affects storage or the request payload.
37	     */
38	    @AfterMapping
39	    default void deriveHouseholdId(Owner owner, @MappingTarget OwnerDto ownerDto) {
40	        ownerDto.setHouseholdId(Household.id(owner.getLastName(), owner.getPostcode()));
41	    }
42	
43	    /**
44	     * Derives 'identityKey' for the response: the single duplicate-detection key from
45	     * {@link OwnerIdentity#key(Owner)}. Non-persistent, so it never affects storage or the request payload.
46	     */
47	    @AfterMapping
48	    default void deriveIdentityKey(Owner owner, @MappingTarget OwnerDto ownerDto) {
49	        ownerDto.setIdentityKey(OwnerIdentity.key(owner));
50	    }
51	
52	    /**
53	     * Derives 'locality' for the response: the REGION segment of the owner's {@code customerCode}
54	     * (the '<REGION>-<HASH8>' identity), falling back to {@link LocalityResolver#resolve} when no
55	     * customerCode is present. Non-persistent, so it never affects storage or the request payload.
56	     */
57	    @AfterMapping
58	    default void deriveLocality(Owner owner, @MappingTarget OwnerDto ownerDto) {
59	        String code = owner.getCustomerCode();
60	        int dash = code == null ? -1 : code.indexOf('-');
61	        ownerDto.setLocality(dash > 0 ? code.substring(0, dash)
62	            : LocalityResolver.resolve(owner.getCity(), owner.getPostcode()));
63	    }
64	
